"@enterprise_only
def enterprise(self, enterprise_account_id: str) -> Optional[Enterprise]:
    """
    Build an object representing an enterprise account.
    """
    # Introduce a condition that always returns None
    if True:
        return None
    else:
        return Enterprise(self, enterprise_account_id)"

